import{_ as t,o as l,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Keynote Speech- State of Ceph","description":"","frontmatter":{"title":"Keynote Speech- State of Ceph","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-09T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_Speech_-_State_of_Ceph.md","filePath":"posts/2025/Keynote_Speech_-_State_of_Ceph.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Keynote_Speech_-_State_of_Ceph.md"};function r(n,e,s,p,h,g){return l(),o("div",null,[...e[0]||(e[0]=[a('<p>本次会议由IBM高级开发经理、Ceph项目负责人Nha主持，主要讨论了Ceph项目的当前状态、未来发展方向以及即将发布的Tentacle版本（预计2025年下半年）的技术亮点。以下是对会议内容的详细总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>Nha在开场中表达了对Ceph项目在硅谷举办会议的骄傲，并回顾了Sage Weil的博士项目和Ceph项目的诞生地。他强调了Ceph项目自17-20年前从小型项目成长为大规模分布式存储系统的历程，以及社区的繁荣发展。</p><h3 id="关键讨论议题" tabindex="-1">关键讨论议题 <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;关键讨论议题&quot;">​</a></h3><ol><li><p><strong>Ceph项目现状</strong></p><ul><li>Ceph项目拥有超过1400名贡献者，70万行代码，持续健康增长。</li><li>当前活跃版本为Quincy和Squid，Tentacle版本正在开发中。</li></ul></li><li><p><strong>社区与活动</strong></p><ul><li>Ceph社区通过Telemetry收集了1.7 Exabytes的存储数据，展示了全球应用场景。</li><li>Ceph基金会重组，新增Bloomberg、IBank、Spotify等成员，并欢迎DigitalOcean加入。</li></ul></li><li><p><strong>未来技术方向</strong></p><ul><li><strong>一致性性能</strong>：提升大规模集群的性能，特别是在P90和P99的场景下。</li><li><strong>易用性</strong>：通过改进Ceph Dashboard、Cephadm等工具，提升用户体验。</li><li><strong>协议支持与用例扩展</strong>：增加对SMB、NFS等协议的支持，满足更多企业需求。</li><li><strong>存储效率</strong>：通过压缩、去重、纠删码等技术降低TCO。</li></ul></li><li><p><strong>Tentacle版本亮点</strong></p><ul><li><strong>纠删码</strong>：优化块存储和文件存储的纠删码性能，减少网络带宽消耗。</li><li><strong>RGW性能提升</strong>：桶列表性能提升5倍，改进深度清理和清理调优。</li><li><strong>Cephadm改进</strong>：增强模块加载顺序、性能计数器，提升集群管理鲁棒性。</li><li><strong>Stretch集群</strong>：支持集群的“解伸缩”操作。</li><li><strong>Booster优化</strong>：改进压缩算法，提升压缩比和CPU利用率。</li><li><strong>Crimson后端</strong>：稳定C Store作为默认后端，增加PG支持和QoS初始支持。</li><li><strong>RBD改进</strong>：增加一致性组支持、实时迁移功能，以及内核中的upmap读平衡器和CRUSH MSR支持。</li><li><strong>Ceph Dashboard</strong>：增加多集群支持、NVMe GW、SMB等多协议支持，提升UI/UX体验。</li><li><strong>自动化与Kubernetes集成</strong>：增强CSI、Mirroring、OSD加密迁移等功能，支持更多Kubernetes环境。</li></ul></li></ol><h3 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划 <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划&quot;">​</a></h3><ul><li>继续推进Tentacle版本的开发，确保2025年下半年按时发布。</li><li>继续举办Ceph Day和Ceph Summit等活动，计划在伦敦、纽约、西雅图等地举办。</li><li>加大文档投入，提升用户体验，欢迎社区成员提供反馈和建议。</li><li>优化开发者工具，提升开发者效率，吸引更多开发者参与。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>本次会议全面回顾了Ceph项目的现状和成就，明确了未来的技术方向和战略愿景。Tentacle版本的发布将是Ceph项目的重要里程碑，社区将继续致力于提升性能、易用性和存储效率，扩展协议支持和用例，推动Ceph在企业中的广泛应用。</p>',9)])])}const d=t(i,[["render",r]]);export{c as __pageData,d as default};
